const items = ['Custom Software','Cloud Architecture','Mobile Apps','AI & Machine Learning','Cybersecurity','DevOps','ERP Integration','Data Analytics','IT Consulting','Digital Transformation'];

export default function Ticker() {
  return (
    <div style={{overflow:'hidden',borderTop:'1px solid rgba(0,200,255,.08)',borderBottom:'1px solid rgba(0,200,255,.08)',background:'#080f1e',padding:'.75rem 0'}}>
      <style>{`@keyframes tick{from{transform:translateX(0)}to{transform:translateX(-50%)}}`}</style>
      <div style={{display:'flex',width:'max-content',animation:'tick 30s linear infinite'}}>
        {[...items,...items].map((item,i)=>(
          <span key={i} style={{padding:'0 2rem',whiteSpace:'nowrap',fontFamily:'Rajdhani,sans-serif',fontSize:'.68rem',fontWeight:600,letterSpacing:'.2em',textTransform:'uppercase',color:'#2a3a50',display:'flex',alignItems:'center',gap:'.7rem'}}>
            {item}<span style={{color:'#00a8e8',fontSize:'.5rem',opacity:.6}}>◈</span>
          </span>
        ))}
      </div>
    </div>
  );
}
